public String id(String entityId) {
    // Algorithm: Traverse the contact database to find the contact with the specified entity ID.
    // Steps:
    // 1. Get the root of the contact database as the starting node.
    // 2. Navigate through the database by comparing the entity ID with each contact's entity ID.
    // 3. When a match is found, return the row ID of the contact.
    // 4. If the entity ID is not found in the database, return null.

    // Implementation:
    Contact root = contactsDb.getRoot(); // Step 1: Get the root node
    Contact currentLeaf = root; // Step 2: Navigate to the root node

    for (char c : entityId.toCharArray()) { // Step 3: Compare entity IDs
        Person nextLeaf = null;
        for (Person person : currentLeaf.getPeople()) {
            if (person.getEntityid().equals(String.valueOf(c))) {
                nextLeaf = person;
                break; // Found a match
            }
        }
        if (nextLeaf == null) {
            return null; // Not found
        }
        currentLeaf = nextLeaf; // Move to the next person in the same line
    }

    if (currentLeaf == null) {
        return null; // Not found
    }

    // Step 4: Return the row ID if found, otherwise return null
    return currentLeaf.getRowId();
}
