public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    GenericSuperclass<?>[] generics = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[generics.length];
    for (int i = 0; i < generics.length; i++) {
        if (generics[i] instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) generics[i];
            if (wildcardType.getLowerBound() == null && wildcardType.getUpperBound() != null) {
                resolvedArguments[i] = wildcardType.getUpperBound();
            } else {
                return null;
            }
        } else {
            Class<?> rawType = (Class<?>) generics[i];
            if (!rawType.isAssignableFrom(targetType)) {
                return null;
            }
            resolvedArguments[i] = rawType;
        }
    }
    return resolvedArguments;
}
