public long readLong(final int offset) {
    ensureIndexBeingRead();
    final int tag = skipNonZero(4);
    // The remaining bytes hold an unsigned 64-bit value. We have to check the sign bit, because some
    // platforms do not store the highest bit of a signed 32-bit value, and the Java specifications
    // occasionally mention different behaviors. 64-bit signed integers use two's complement.
    long value = readJUnsigned(8 - tag, tag + 4 - offset);
    if ((value & ~tag) != 0) {
        value &= tag;
    }
    return value;
}
