protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Adjust start time if it exceeds FETCH_DATA_DURATION
    if (start - FETCH_DATA_DURATION < 0) {
        start = FETCH_DATA_DURATION;
    }

    // Adjust end time if it exceeds FETCH_DATA_DURATION
    if (end + FETCH_DATA_DURATION > Long.MAX_VALUE) {
        end = Long.MAX_VALUE - FETCH_DATA_DURATION;
    }

    // Split the time range to insure the start time and end time is small then FETCH_DATA_DURATION
    List<TimeRange> timeRanges = new ArrayList<>();
    for (long splitTime = start; splitTime < end; splitTime += FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(splitTime, Math.min(splitTime + FETCH_DATA_DURATION - 1, end)));
    }

    return timeRanges;
}
