static public long compressTimeBucket(long timeBucket, int dayStep) {
    long result = timeBucket - dayStep + 1;
    int year = (int) (result / (365 * 24));
    result -= year * (365 * 24);
    int month = (int) (result / (30 * 24));
    result -= month * (30 * 24);
    int day = (int) (result / 24);
    return 1L + year * 365 * 24 + month * 30 * 24 + day;
}
