        index++;
        l++;
    }
    // Handle special unicode characters including surrogates and closed Unicode planes
    while (index < str.length()) {
        int c = str.charAt(index);
        if (c < 0xD800 && c > 0xDFFF) { // Surrogate pair
            index++;
        } else if ((c & 0xF800) == 0xD800) { // Starting of a surrogate pair
            while (index < str.length() && (str.charAt(index) & 0xFC00) != 0xDC00) {
                index++;
            }
            if (index >= str.length() || (str.charAt(index) & 0xFC00) != 0xDC00) {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
            index++;
        } else { // Non-surrogate and standalone character
            l += Character.charCount(c);
        }
    }
    return l;
}
