public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity == 0)
        return;

    int capacity = desiredCapacity + 11; // Ensure the returned capacity is close to desiredCapacity but has a margin of 11%
    if (capacity < 32 && desiredCapacity > 11) {
        capacity = (nextPrime(32) + 1) / 2 * 2 + 1; // Use the next prime number if the initial capacity is less than 32
    }

    int delta = capacity - nextPrime(nextPrime(capacity)); // Calculate the number of steps from the initial capacity to the next prime number
    int prime = nextPrime(capacity) - delta / 2; // The next prime number is approximately half of the steps from the initial capacity

    if (desiredCapacity >= 1000)
        prime = (prime / 10) * 10; // Ensure the returned prime number is very close to desiredCapacity

    return prime;
}
