private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> contentMap = new HashMap<>();

    try {
        // Iterate through all key-value pairs in the jsonObject
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement value = entry.getValue();

            // Check if the value is recognized (example for parsing strings)
            if (value.isString()) {
                String stringValue = value.getAsString();
                contentMap.put(key, stringValue); // Store the string value in the map
            } else if (value.isNumber()) {
                double numberValue = value.getAsDouble();
                contentMap.put(key, numberValue); // Store the double value in the map
            } else if (value.isBoolean()) {
                boolean booleanValue = value.getAsBoolean();
                contentMap.put(key, booleanValue); // Store the boolean value in the map
            } else if (value.isJsonArray()) {
                List<Object> array = new ArrayList<>();
                for (JsonElement arrayElement : value.getAsJsonArray()) {
                    array.add(arrayElement.getAsObject());
                }
                contentMap.put(key, array); // Store the array value in the map
            } else if (value.isJsonObject()) {
                Map<String, Object> subMap = buildContent(arrayElement.getAsJsonObject());
                contentMap.put(key, subMap); // Recursively build content for nested objects
            }
        }
    } catch (Exception e) {
        // Handle exceptions such as missing or unknown JSON types
        e.printStackTrace();
    }

    return contentMap;
}
