private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Check if the stop node is within the range of the start and end nodes
    if (stop.compareTo(start) < 0) {
        return start;
    }
    // Traverse the graph in the specified direction to find the node satisfying the predicate
    while (stop != start && !predicate.test(stop)) {
        if (dir == DIR_FORWARD) {
            start = directionStep(start, 1);
        } else if (dir == DIR_BACKWARD) {
            start = directionStep(start, -1);
        }
    }
    return start;
}
