private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Long> suffixSums = new ArrayList<>();
    Iterator<Integer> iter = bounds.iterator();
    if (iter.hasNext()) {
        Long sum = iter.next();
        suffixSums.add(sum);
        while (iter.hasNext()) {
            sum += iter.next();
            suffixSums.add(sum);
        }
    }
    List<Integer> finalList = new ArrayList<>();
    for (var sum : suffixSums) {
        finalList.add((int)sum);
    }
    return new Pair<>(finalList, suffixSums.stream().mapToLong(Long::longValue).sum());
}
