private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
  if (graph == null || vertices == null || vertices.isEmpty()) {
    throw new IllegalArgumentException("Graph or vertices should not be null or empty.");
  }

  // Check if there's a single element in the set, which means it's a clique by default.
  if (vertices.size() == 1) {
    return true;
  }

  // Check if all vertices have an edge to every other vertex in the set.
  for (V v : vertices) {
    if (vertices.contains(v)) {
      continue; // Skip the current vertex.

      for (V w : vertices) {
        if (v.equals(w)) {
          continue; // Skip the edge between the same vertex.

        }
        if (!graph.hasEdge(v, w)) {
          return false; // Found a vertex that's not connected to every other vertex in the set.
        }
      }
    }
  }

  return true;
}
