            sb.append(path.charAt(i));
            continue;
        }
        if (i == path.length() - 1) {
            sb.append(relativePath.substring(i));
        }
    }
    if (i < path.length() && path.charAt(i) == '/' || path.charAt(i) == '\\' || path.charAt(i) == ':') {
        sb.append(relativePath.substring(i));
    }
    return sb.toString();
