static String[] toNoNullStringArray(Object[] array){
    int size = 0;
    for (Object obj : array) {
        if (obj != null) {
            size++;
        }
    }

    if (size == array.length) {
        return array;
    }

    String[] result = new String[size];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (String) obj;
        }
    }

    return result;
}
