private String buildContentRange(){
    long contentLength = getContentSize();
    if (contentLength <= 0) {
        return "bytes */1";
    }
    long offset = getOffset();
    if (offset == 0) {
        return "bytes 0-" + (contentLength - 1) + "/" + contentLength;
    }
    long end = (offset + contentLength - 1) > contentLength ? contentLength - 1 : offset + contentLength - 1;
    return "bytes " + offset + "-" + end + "/" + contentLength;
}
